# Hand-written explanations of the application settings (ClientApplicationSettings). A null value means "use the project's value".
N = {}
def n(path, what, when, why, ex=None): N[path] = dict(what=what, when=when, why=why, ex=ex)

n('SchemaVersion', 'The version of the JSON layout of the application settings.', 'Never by hand.', 'Lets a later Server convert old settings.')
n('UiMode', 'The intended sign-in mode of this application (`Hosted`, `Self`, `None`); `null` uses `Clients.DefaultUiMode` of the project. **The Server does not enforce it**: the Client package chooses the mode with `UseHostedUi()` or `UseSelfUi()`. What the Server enforces for a Self UI is `AllowSelfUiLogin`. See [enums-reference.md](enums-reference.md#uimode).', 'To record how this application is meant to sign in.', 'It documents the plan for admins reading the application page.', 'Hosted')
n('CookieLifetimeMinutes', 'How long the sign-in cookie of this application lasts. Read by the Client at the handshake as the default cookie lifetime (`Auth2CookieOptions.ExpireTimeSpan = null`); `null` uses the project value.', 'A banking app wants 15 minutes, an internal tool 12 hours.', 'The cookie lifetime is a product decision per application, not per project.', 60)
n('AccessTokenMinutes', 'The access token lifetime for this application (1 to 1440). `null` uses the project value.', 'Shorter for a sensitive API, longer for a mobile client that cannot refresh often.', 'Applications of one project can have different risk.', 5)
n('RefreshTokenDays', 'The refresh token lifetime for this application. `null` uses the project value.', 'Longer for an app people open rarely.', 'It is how long someone stays signed in without typing a password.', 90)
n('IdentityTokenMinutes', 'The identity token lifetime for this application. `null` uses the project value.', 'Rarely.', 'The identity token is read once at sign-in.', 5)
n('AllowedCorsOrigins', 'The browser origins that may call the Server from JavaScript for this application (CORS). Empty means CORS is off. A value must be an `http(s)` origin without a wildcard.', 'A single-page app on another origin that calls the token endpoint.', 'The Server only answers cross-origin calls from origins you list.', ['https://app.example.com'])
n('AllowClientToSetWebServerUrl', 'Lets the client of this application tell the Server, in its handshake (`Auth2ClientOptions.WebServerUrl`, `ApplicationType`), the web server address and the type of the application; the Server stores them. Off: only a global admin sets them and the handshake answer says `webServerLocked`. See [handshake-and-startup.md](handshake-and-startup.md#the-web-server-address-and-the-application-type).', 'Turn off when the address is managed by admins (for example behind a gateway).', 'The address is where the Server sends health checks, so only a developer decides who may set it.', True)
n('AllowSelfUiLogin', '**The switch for the Self UI.** When on, the application may use the password grant and the two-factor grants, so its own form can send a password to the Server. When off those grants are removed from the OpenIddict application. See [client-setup.md](client-setup.md#self-ui).', 'Only for an application that shows its own login form, or that signs in directory (LDAP) users through the token endpoint.', 'The application then handles passwords. The hosted sign-in (default) never lets it see one.', True)
n('ExternalProviders', 'The names of the project\'s external providers this application shows. `null` shows all of them. It is a **subset only**: it never adds a provider the project does not have.', 'One project, two applications: the partner portal shows only the company SAML button, the public site shows Google and GitHub.', 'Different applications of one project need different buttons without copying the providers.', ['google', 'github'])
n('ConsentMode', 'The consent mode for this application (`Implicit`, `Explicit`, `Systematic`), overriding the project. `null` uses the project value (and `Sessions.RequireConsent`). See [enums-reference.md](enums-reference.md#consentmode).', 'A third-party application should ask; your own should not.', 'It maps to the consent type of the OpenIddict application.', 'Explicit')
n('SendConfirmationEmail', 'Send the confirmation email after registration through this application. `null` uses `Registration.SendConfirmationEmail` of the project. Always sent when `Email.RequireConfirmedEmail` is on.', 'When one application confirms emails itself.', 'Lets applications of one project behave differently.', False)
n('Messaging', 'This application\'s own email and SMS providers (`MessagingSettings`). `null` uses the project\'s. Changed only through the messaging admin routes, because it holds a password. See [email-and-sms.md](email-and-sms.md).', 'When an application must send from its own mail account.', 'One server, many applications, each with its own sender.', None)
